mapper.select:
SELECT
    JSONExtractString(ifNull(r.metadata, '{}'), 'serving', 'sealed_source') AS sealed_source,
    JSONExtract(ifNull(r.metadata, '{}'), 'serving', 'thumbnail_width', 'Nullable(UInt32)') AS thumbnail_width,
    JSONExtract(ifNull(r.metadata, '{}'), 'serving', 'thumbnail_height', 'Nullable(UInt32)') AS thumbnail_height
FROM resource r
PREWHERE r.cancer_study_id = (
        SELECT cancer_study_id FROM cancer_study WHERE cancer_study_identifier = #{studyId}
    )
    AND r.resource_id = #{resourceId}
    AND r.patient_id = #{patientId}
WHERE JSONExtractString(ifNull(r.metadata, '{}'), 'serving', 'key') = #{key}
LIMIT 1
